key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
gi=GalaxyInstance('https://usegalaxy.org', key=key)
tid='ucsc_table_direct1'
r=gi.tools.build(tid, history_id='bbd44e69cb8906b5f2a96fe6c27228c1')
print('errors', json.dumps(r.get('errors'), indent=2))
print('state_inputs', json.dumps(r.get('state_inputs'), indent=2))
# recursively print inputs with value
def walk(x,path=''):
    if isinstance(x,dict):
        if 'name' in x and 'type' in x:
            print(path or x.get('name'), '|', x.get('type'), '| value=', repr(x.get('value')), '| text=', repr(x.get('text_value')), '| options=', (list(x.get('options',{}).keys()) if isinstance(x.get('options'),dict) else x.get('options')), '| errors=', x.get('errors'))
            if x.get('inputs'):
                for c in x['inputs']: walk(c,path+'/'+c.get('name','?'))
        else:
            for k,v in x.items(): walk(v,path+'/'+k)
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+f'[{i}]')
for inp in r.get('inputs',[]): walk(inp)
